#include <bits/stdc++.h>
using namespace std;

const int MOD1=998244353;
const int MOD2=1000000007;
long long n;
int digits[15], base[15], answer;

long long getNumber(int *arr, int length){
    long long result=0;
    for (int i=1; i<=length; i++)
        result=result*10+arr[i];
    return result;
}

long long computeRank(int *arr, int length){
    long long total=0;
    for (int digit=1; digit<=*digits; digit++){
        for (int i=1; i<=min(length,digit); i++){
            for (int j=(i==1?1:0); j<arr[i]; j++){
                long long leftPart=0, rightPart=0;
                for (int p=1; p<i; p++)
                    leftPart=rightPart=leftPart*10+arr[p];
                leftPart=rightPart=leftPart*10+j;
                for (int p=i+1; p<=digit; p++)
                    leftPart=leftPart*10, rightPart=rightPart*10+9;
                rightPart=min(rightPart, n);
                if (leftPart<=rightPart)
                    total+=rightPart-leftPart+1;
            }
        }
        if (digit<=length) ++total;
    }
    return total;
}

int computeF(int *arr, int length){
    return ((-getNumber(arr,length)+computeRank(arr,length))%MOD1+MOD1)%MOD1;
}

int diff[15];
int q1[1000010], q2[1000010];
long long q2sum[1000010];

void dfs(int start, int end, int *q, int v){
    if (start==end){
        for (int i=0; i<=9; i++)
            q[++*q]=(v+1LL*i*diff[start])%MOD1;
        return;
    }
    for (int i=0; i<=9; i++)
        dfs(start+1, end, q, (v+1LL*i*diff[start])%MOD1);
}

void update(int length, int index, int value){
    int backup[15];
    memcpy(backup, digits, sizeof(digits));
    digits[index]=value;
    for (int p=index+1; p<=length; p++) digits[p]=0;
    int baseVal=computeF(digits,length);
    for (int p=index+1; p<=length; p++){
        digits[p]=1;
        diff[p]=(computeF(digits,length)+MOD1-baseVal)%MOD1;
        digits[p]=0;
    }
    if (length-index==0){
        answer=(answer+baseVal)%MOD2;
        return;
    }
    if (length-index==1){
        for (int p=0; p<=9; p++)
            answer=(answer+(baseVal+1LL*p*diff[length])%MOD1)%MOD2;
        return;
    }
    int mid=(length+index)/2;
    *q1=0; *q2=0;
    dfs(index+1, mid, q1, baseVal);
    dfs(mid+1, length, q2, 0);
    std::sort(q2+1, q2+*q2+1);
    long long sumQ2=0;
    for (int i=1; i<=*q2; i++)
        sumQ2=(sumQ2+q2[i])%MOD2;
    for (int i=1; i<=*q1; i++){
        int p=lower_bound(q2+1, q2+*q2+1, MOD1 - q1[i]) - q2;
        answer=(answer+sumQ2+1LL*(*q2)*q1[i])%MOD2;
        answer=(answer+1LL*((*q2)-p+1)*(MOD2-MOD1))%MOD2;
    }
}

int main(){
    scanf("%lld", &n);
    long long m=n;
    for (*digits=0; m; m/=10) digits[++*digits]=m%10;
    std::reverse(digits+1, digits+*digits+1);
    for (int d=1; d<=*digits; d++){
        for (int i=1; i<=d; i++){
            int l=(i==1?1:0);
            int r=(d==*digits?digits[i]-1:9);
            for (int j=l; j<=r; j++)
                if (j!=digits[i]) update(d, i, j);
        }
        answer=(answer+computeF(digits, d))%MOD2;
    }
    printf("%d\n", answer);
}
